function asErrTxt(e,who){var s=e&&e.st;if(s===401||s===403||s===400&&who==='Gemini')return 'a chave '+(who==='Groq'?'da Groq':'do Gemini')+' não foi aceita. Confira em Mais → Ajustes.';if(s===413)return 'a pergunta ficou grande demais para o limite grátis da '+who+'. Tente perguntar sobre uma empresa por vez, ou toque em Limpar conversa.';if(s===429)return 'limite de uso '+(who==='Groq'?'da Groq':'do Gemini')+' atingido por agora. Tente de novo em 1 minuto.';if(s>=500)return who+' está fora do ar agora.';return who+': '+(e&&e.message==='Failed to fetch'?'sem internet ou bloqueado':e&&e.message||'erro')}
